<?php use Dilemma\Views; use Dilemma\Support; ?>
<section class="reading wide"><h1><?= $t('settings') ?></h1><?= Views::form('/api/profile', 'saved') ?><?= Views::field('alias', 'alias', $user['alias'], 'text', true, 60) ?><p class="muted"><?= $t('alias_help') ?></p><fieldset class="avatar-picker"><legend><?= $t('avatar') ?></legend><?php foreach (['', 'circle', 'leaf', 'spark', 'wave'] as $avatar): ?><label><input type="radio" name="avatar" value="<?= $avatar ?>" <?= $user['avatar'] === $avatar ? 'checked' : '' ?>><?= Views::avatar($avatar) ?><span><?= $t('avatar_' . ($avatar ?: 'none')) ?></span></label><?php endforeach; ?></fieldset><?= Views::area('bio', 'bio', $user['bio'], false, 500) ?><label class="field"><span><?= $t('language') ?></span><select name="locale"><option value="sv" <?= $user['locale'] === 'sv' ? 'selected' : '' ?>>Svenska</option><option value="en" <?= $user['locale'] === 'en' ? 'selected' : '' ?>>English</option></select></label><?= Views::check('notify', 'notify', (bool) $user['notify']) ?><?= Views::field('chat_link', 'chat_link', $user['chat_link'] ? Support::unseal($user['chat_link']) : '', 'url', false, 2000) ?><p class="muted"><?= $t('chat_help') ?></p><?= Views::submit('save') ?></form>
<?= Views::render('pwa', []) ?>
<div class="account-data"><h2><?= $t('privacy') ?></h2><a class="button secondary" href="/api/export" download><?= $t('export') ?></a><details class="danger-zone"><summary><?= $t('delete_account') ?></summary><p><?= $t('delete_help') ?></p><?= Views::form('/api/delete', 'deleted', 'data-confirm="delete_confirm"') ?><?= Views::field('email', 'email', '', 'email', true, 254) ?><?= Views::submit('delete_account', 'danger') ?></form></details></div></section>
